import * as T from './vendor/three.module.js';
import {addArchitecture} from './architecture.js';
import {HDRLoader} from './vendor/HDRLoader.js';
export {T};
const S=1/1.5;
function material(color,extra={}){return new T.MeshStandardMaterial({color,roughness:.86,...extra})}
export function buildCity(canvas){
 const renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.94;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
 const scene=new T.Scene();scene.background=new T.Color('#aac7d6');scene.fog=new T.Fog('#bccdd0',160,620);
 const camera=new T.PerspectiveCamera(62,innerWidth/innerHeight,.08,850);
 scene.add(new T.HemisphereLight('#d2dfef','#796b51',1.0));const sun=new T.DirectionalLight('#ffddac',3.1);sun.position.set(820,90,2120);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-32;sun.shadow.camera.right=32;sun.shadow.camera.top=32;sun.shadow.camera.bottom=-32;sun.shadow.camera.near=1;sun.shadow.camera.far=220;sun.shadow.bias=-.00012;sun.shadow.normalBias=.12;scene.add(sun,sun.target);
 const ground=new T.Mesh(new T.PlaneGeometry(Geo.W*S+1000,Geo.H*S+1000),material('#a7ab8d'));ground.rotation.x=-Math.PI/2;ground.position.set(Geo.W*S/2,-.08,Geo.H*S/2);ground.receiveShadow=true;scene.add(ground);
 const {wallMeshes,buildingCount,special,materials}=addArchitecture(scene,renderer);
 const texLoader=new T.TextureLoader();function surfaceTexture(name){let t=texLoader.load('assets/materials/'+name);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return t}const asphaltTexture=surfaceTexture('asphalt-color.jpg'),cementTexture=surfaceTexture('concrete-color.jpg');
 const skyCanvas=document.createElement('canvas');skyCanvas.width=2048;skyCanvas.height=1024;let sky=skyCanvas.getContext('2d'),gradient=sky.createLinearGradient(0,0,0,1024);gradient.addColorStop(0,'#375c86');gradient.addColorStop(.34,'#8ba9c2');gradient.addColorStop(.5,'#dfc4a0');gradient.addColorStop(.56,'#c8b99f');gradient.addColorStop(1,'#737a72');sky.fillStyle=gradient;sky.fillRect(0,0,2048,1024);for(let i=0;i<80;i++){let x=(i*391)%2048,y=170+(i*47)%270;let grad=sky.createRadialGradient(x,y,0,x,y,95);grad.addColorStop(0,'#e9dfce28');grad.addColorStop(1,'#e9dfce00');sky.fillStyle=grad;sky.fillRect(x-110,y-110,220,220)}let skyTexture=new T.CanvasTexture(skyCanvas);skyTexture.mapping=T.EquirectangularReflectionMapping;skyTexture.colorSpace=T.SRGBColorSpace;scene.background=skyTexture;scene.fog=new T.Fog('#c4bda9',180,850);
 const pmrem=new T.PMREMGenerator(renderer);new HDRLoader().load('assets/materials/sunset.hdr',hdr=>{hdr.mapping=T.EquirectangularReflectionMapping;scene.environment=pmrem.fromEquirectangular(hdr).texture;scene.environmentIntensity=.55;hdr.dispose();pmrem.dispose()});
 function tri(b,a,c,d,col,uv=[[0,0],[1,0],[0,1]]){b.p.push(...a,...c,...d);for(let i=0;i<3;i++){b.col.push(col.r,col.g,col.b);b.uv.push(...uv[i])}}
 function quad(b,a,c,d,e,col,u=1,v=1){tri(b,a,c,d,col,[[0,0],[u,0],[u,v]]);tri(b,a,d,e,col,[[0,0],[u,v],[0,v]])}
 // Road, sidewalk and park surfaces retain the source map coordinates.
 const surfaceBatches=new Map();function surface(color){return batchSurface(color)}function batchSurface(color){if(!surfaceBatches.has(color))surfaceBatches.set(color,{p:[],col:[],uv:[],color});return surfaceBatches.get(color)}
 function poly(p,y,color){if(p.length<3)return;let ps=p.map(v=>new T.Vector2(v[0]*S,v[1]*S));if(ps[0].distanceTo(ps.at(-1))<.01)ps.pop();let b=surface(color),col=new T.Color(color);for(const f of T.ShapeUtils.triangulateShape(ps,[]))tri(b,...f.map(i=>[ps[i].x,y,ps[i].y]),col)}
 for(const a of Geo.areas)poly(a.p,.005,a.type==='pitch'?'#6d8e64':'#6f8b5b');
 for(const w of Geo.waterAll)poly(w.p,.015,'#4a8795');
 function strip(p,width,y,color){let b=surface(color),col=new T.Color(color);for(let i=1;i<p.length;i++){let a=p[i-1],e=p[i],dx=e[0]-a[0],dz=e[1]-a[1],len=Math.hypot(dx,dz);if(!len)continue;let nx=-dz/len*width*S/2,nz=dx/len*width*S/2;quad(b,[a[0]*S+nx,y,a[1]*S+nz],[e[0]*S+nx,y,e[1]*S+nz],[e[0]*S-nx,y,e[1]*S-nz],[a[0]*S-nx,y,a[1]*S-nz],col)}}
 for(const r of Geo.roads){strip(r.p,r.width+(r.drive?6:2),.045,'#c3c0ad')}
 for(const r of Geo.roads){strip(r.p,r.width,.065,r.drive?'#555e61':'#cfc8b1');if(r.drive&&r.width>18){for(let i=1;i<r.p.length;i++){let a=r.p[i-1],e=r.p[i],dx=e[0]-a[0],dz=e[1]-a[1],len=Math.hypot(dx,dz);for(let j=3;j<len;j+=18){let t=j/len,t2=Math.min(j+7,len)/len;strip([[a[0]+dx*t,a[1]+dz*t],[a[0]+dx*t2,a[1]+dz*t2]],.24,.08,'#e2d29e')}}}}
 for(const s of Geo.streams)if(s.tunnel==='no')strip(s.p,s.type==='river'?11:4,.03,'#4a8795');
 const waterSurfaces=[];for(const b of surfaceBatches.values()){let geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(b.p,3));let uv=[];for(let i=0;i<b.p.length;i+=3)uv.push(b.p[i]/3,b.p[i+2]/3);geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.computeVertexNormals();let isRoad=b.color==='#555e61',isCement=b.color==='#c3c0ad',isWater=b.color==='#4a8795';let m=material(isRoad?'#a4a4a0':isCement?'#ded9c9':b.color,{map:isRoad?asphaltTexture:isCement?cementTexture:null,side:T.DoubleSide,roughness:isWater?.18:.94,metalness:isWater?.35:0});if(isWater){m.onBeforeCompile=shader=>{shader.uniforms.waterTime={value:0};shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nuniform float waterTime;').replace('#include <color_fragment>','#include <color_fragment>\n diffuseColor.rgb *= 0.95 + 0.05*sin(vMapUv.x*5.0+waterTime)*sin(vMapUv.y*3.0-waterTime*0.6);');waterSurfaces.push(shader.uniforms.waterTime)};m.map=cementTexture}let mesh=new T.Mesh(geo,m);mesh.receiveShadow=true;scene.add(mesh)}

 // Small repeated details are instanced rather than individual draw calls.
 let seed=913;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};const check=document.createElement('canvas').getContext('2d');const treePts=[];
 for(const area of Geo.areas){let box=area.box,attempts=Math.min(130,Math.floor((box.r-box.x)*(box.b-box.y)/1800));for(let i=0;i<attempts;i++){let x=box.x+rand()*(box.r-box.x),z=box.y+rand()*(box.b-box.y);if(x<0||z<0||x>Geo.W||z>Geo.H||!check.isPointInPath(area.path,x,z)||Geo.blocked(x,z))continue;let near=Geo.nearestRoad(x,z);if(near.distance<near.r.width/2+6)continue;treePts.push({x:x*S,z:z*S,s:.7+rand()*.8})}}
 function instance(geometry,mat,points,compose){let mesh=new T.InstancedMesh(geometry,mat,points.length),o=new T.Object3D();for(let i=0;i<points.length;i++){compose(o,points[i]);o.updateMatrix();mesh.setMatrixAt(i,o.matrix)}mesh.castShadow=true;mesh.receiveShadow=true;scene.add(mesh);return mesh}
 instance(new T.CylinderGeometry(.13,.18,2.4,6),material('#77614c'),treePts,(o,p)=>{o.position.set(p.x,1.2*p.s,p.z);o.scale.setScalar(p.s)});
 instance(new T.IcosahedronGeometry(2.1,2),material('#667958',{flatShading:false}),treePts,(o,p)=>{o.position.set(p.x,3.5*p.s,p.z);o.scale.set(p.s,p.s*1.15,p.s)});
 const poles=[];for(let i=0;i<Geo.roads.length;i++){let r=Geo.roads[i];if(!r.drive||!r.name||i%3)continue;let p=Geo.routePoint(r,15);if(p.x<0||p.y<0||p.x>Geo.W||p.y>Geo.H)continue;let off=(r.width/2+2)*S;poles.push({x:p.x*S-Math.sin(p.angle)*off,z:p.y*S+Math.cos(p.angle)*off})}
 instance(new T.CylinderGeometry(.045,.07,5.8,5),material('#5f6b66'),poles,(o,p)=>{o.position.set(p.x,2.9,p.z);o.scale.set(1,1,1)});instance(new T.BoxGeometry(.45,.16,.7),material('#e5e3c6',{emissive:'#b4a66c',emissiveIntensity:.2}),poles,(o,p)=>{o.position.set(p.x,5.85,p.z);o.scale.set(1,1,1)});
 function sign(text,x,y,z,width=4){let ca=document.createElement('canvas');ca.width=512;ca.height=96;let co=ca.getContext('2d');co.fillStyle='#203c35';co.fillRect(0,0,512,96);co.strokeStyle='#e0e7cc';co.lineWidth=5;co.strokeRect(5,5,502,86);co.fillStyle='#f0f2dc';co.font='600 30px sans-serif';co.textAlign='center';co.fillText(text,256,59,480);let tex=new T.CanvasTexture(ca);tex.colorSpace=T.SRGBColorSpace;let sprite=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:true}));sprite.scale.set(width,width*96/512,1);sprite.position.set(x,y,z);scene.add(sprite);return sprite}
 const named=new Set();for(const r of Geo.roads){if(!r.name||named.has(r.name)||r.type==='service'||!r.drive)continue;let p=Geo.routePoint(r,8);if(p.x<100||p.y<100||p.x>Geo.W-100||p.y>Geo.H-100)continue;named.add(r.name);let off=(r.width/2+1)*S;sign(r.name,p.x*S-Math.sin(p.angle)*off,2.9,p.y*S+Math.cos(p.angle)*off,3)}
 const landmarkObjects=[];function landmark(name,x,z){let ring=new T.Mesh(new T.TorusGeometry(1,.06,6,40),material('#c4f678',{emissive:'#99cc55',emissiveIntensity:.3}));ring.rotation.x=Math.PI/2;ring.position.set(x,.15,z);scene.add(ring);let marker=new T.Mesh(new T.OctahedronGeometry(.28),material('#d7ec9e',{emissive:'#99bb55',emissiveIntensity:.4}));marker.position.set(x,2.7,z);scene.add(marker);let label=sign(name,x,3.5,z,2.5);label.visible=false;landmarkObjects.push({ring,marker,label});return marker}
 function box(w,h,d,col,x=0,y=0,z=0,parent=scene){const m=new T.Mesh(new T.BoxGeometry(w,h,d),material(col));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;parent.add(m);return m}
 // A restrained museum-ship silhouette at Battleship Cove, beside the mapped waterfront.
 const cove=Geo.data.pois.find(p=>p.name==='Battleship Cove'&&p.tags.tourism);if(cove){let x=cove.p[0]*S-18,z=cove.p[1]*S;let ship=new T.Group();ship.position.set(x,.3,z);ship.rotation.y=-.17;scene.add(ship);box(15,3.5,125,'#7d8b8b',0,1.5,0,ship);box(10,2.2,105,'#9aa5a1',0,4.2,0,ship);box(7,7,21,'#8a9997',0,8,0,ship);box(3,11,6,'#687c7c',0,13,0,ship);for(let t of [-40,39]){box(6,2,8,'#a1aaa5',0,6,t,ship);for(let k=-1;k<=1;k++)box(.32,.32,13,'#7d8d89',k*1.2,6.5,t-8,ship)}}
 function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);
 return{renderer,scene,camera,sun,wallMeshes,landmark,landmarkObjects,box,material,buildingCount,special,waterSurfaces};
}
export function makeCharacter(scene){
 const root=new T.Group();scene.add(root);const tan=material('#ad875f',{roughness:.95}),tanDark=material('#937450',{roughness:.95}),white=material('#edece3'),skin=material('#875331'),beard=material('#242723'),gold=material('#c9a153',{metalness:.65,roughness:.3}),black=material('#202622');
 function mesh(geo,mat,x,y,z,parent=root){let m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
 const body=new T.Group();root.add(body);mesh(new T.CylinderGeometry(.285,.24,.62,20),tan,0,1.2,0,body).scale.z=.62;mesh(new T.BoxGeometry(.19,.51,.018),white,0,1.22,.145,body);mesh(new T.BoxGeometry(.04,.54,.025),tanDark,-.12,1.23,.16,body);mesh(new T.BoxGeometry(.04,.54,.025),tanDark,.12,1.23,.16,body);mesh(new T.CylinderGeometry(.095,.10,.13,10),skin,0,1.55,0,body);
 const head=mesh(new T.SphereGeometry(.185,24,20),skin,0,1.76,0,body);head.scale.set(.92,1.12,.94);const chin=mesh(new T.SphereGeometry(.153,14,10),beard,0,1.68,.022,body);chin.scale.set(.98,.72,1.03);mesh(new T.SphereGeometry(.13,12,8),skin,0,1.78,.075,body).scale.set(1,.65,.8);mesh(new T.SphereGeometry(.037,8,6),skin,0,1.76,.173,body).scale.set(.85,1,.8);
 for(const side of [-1,1]){mesh(new T.SphereGeometry(.041,8,6),skin,side*.17,1.76,0,body);mesh(new T.SphereGeometry(.019,8,6),white,side*.065,1.81,.15,body);mesh(new T.SphereGeometry(.010,8,6),black,side*.065,1.811,.166,body);mesh(new T.BoxGeometry(.058,.016,.012),beard,side*.066,1.85,.153,body);mesh(new T.SphereGeometry(.012,8,6),gold,side*.188,1.735,.012,body);let collar=mesh(new T.BoxGeometry(.12,.1,.04),tanDark,side*.15,1.48,.14,body);collar.rotation.z=side*.35}
 let chain=mesh(new T.TorusGeometry(.13,.009,5,24,Math.PI),gold,0,1.42,.16,body);chain.rotation.z=Math.PI;mesh(new T.BoxGeometry(.025,.04,.012),gold,0,1.27,.175,body);
 const arms=[],legs=[];for(let side of [-1,1]){let arm=new T.Group();arm.position.set(side*.32,1.43,0);body.add(arm);mesh(new T.CapsuleGeometry(.10,.31,6,12),tan,0,-.19,0,arm);mesh(new T.CapsuleGeometry(.085,.19,6,12),tanDark,0,-.47,.01,arm);mesh(new T.SphereGeometry(.075,8,8),skin,0,-.65,.01,arm);arms.push(arm);let leg=new T.Group();leg.position.set(side*.14,.94,0);root.add(leg);mesh(new T.CapsuleGeometry(.13,.54,6,12),tan,0,-.34,0,leg);mesh(new T.BoxGeometry(.21,.12,.35),white,0,-.84,.07,leg);mesh(new T.BoxGeometry(.225,.035,.37),white,0,-.91,.07,leg);legs.push(leg)}
 const shade=new T.Mesh(new T.CircleGeometry(.4,24),new T.MeshBasicMaterial({color:'#192b28',transparent:true,opacity:.18,depthWrite:false}));shade.rotation.x=-Math.PI/2;shade.position.y=.09;root.add(shade);
 return{root,update(time,moving,running){const wave=moving?Math.sin(time*(running?13:8)):Math.sin(time*2)*.025,amp=moving?(running?.95:.55):1;legs[0].rotation.x=wave*amp;legs[1].rotation.x=-wave*amp;arms[0].rotation.x=-wave*amp*.8;arms[1].rotation.x=wave*amp*.8;body.position.y=moving?Math.abs(wave)*.035:Math.sin(time*2)*.009;body.rotation.x=running&&moving?.1:0}};
}
export function makeCar(city,color='#bbad79'){
 const root=new T.Group();city.scene.add(root);const box=(w,h,d,col,x,y,z)=>city.box(w,h,d,col,x,y,z,root);box(1.78,.6,4.1,color,0,.66,0);box(1.5,.62,2.05,'#779396',0,1.21,-.1);box(1.54,.1,2.12,color,0,1.57,-.1);box(1.84,.16,.12,'#adb9b5',0,.52,2.08);box(1.84,.16,.12,'#adb9b5',0,.52,-2.08);for(let side of [-1,1]){box(.4,.16,.05,'#f8e5b5',side*.58,.82,2.08);box(.4,.16,.05,'#bd6452',side*.58,.82,-2.08);for(let z of [-1.25,1.25]){let wheel=new T.Mesh(new T.CylinderGeometry(.34,.34,.18,12),city.material('#293330'));wheel.rotation.z=Math.PI/2;wheel.position.set(side*.89,.37,z);root.add(wheel)}}return root;
}
